components.css:
.gh-card { border: 1px solid var(--line); background: var(--surface); border-radius: var(--radius-lg); padding: var(--space-5); max-width: 560px; }
.gh-muted { color: var(--muted); }
.gh-kicker { margin: 0; color: var(--muted); font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; }
.gh-input { flex: 1; min-width: 0; border: 1px solid var(--line); background: var(--surface-strong); color: var(--fg); border-radius: var(--radius-md); padding: 8px 12px; font: inherit; font-size: 14px; }
.gh-btn { border: 1px solid var(--line); border-radius: var(--radius-md); padding: 8px 13px; font: inherit; font-size: 14px; font-weight: 600; color: var(--fg); background: var(--chip); white-space: nowrap; }
.gh-btn-primary { background: var(--accent); border-color: transparent; color: var(--bg); }
.gh-pill { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--chip-line); background: var(--chip); border-radius: 999px; padding: 1px 9px; font-size: 11.5px; color: var(--muted); }
.gh-pill[data-tone="live"] { color: var(--palm); border-color: color-mix(in oklab, var(--palm) 45%, transparent); }
.gh-pill[data-tone="warn"] { color: var(--warn); border-color: rgba(180, 83, 9, 0.35); }
.gh-bubble { margin: 0; border-radius: var(--radius-lg); padding: 9px 13px; font-size: 14px; line-height: 1.45; max-width: 92%; }
.gh-bubble-asked { align-self: flex-end; background: color-mix(in oklab, var(--lagoon) 16%, var(--surface-strong)); border-bottom-right-radius: 4px; }
.gh-bubble-answer { align-self: flex-start; border: 1px solid var(--line); background: var(--surface-strong); border-bottom-left-radius: 4px; }
.gh-bubble-failed { align-self: flex-start; border: 1px solid rgba(180, 83, 9, 0.35); color: var(--warn); }
.who { display: block; font-size: 11px; color: var(--muted); }
.gh-bubble-failed .who { color: var(--warn); }
.row { display: flex; gap: var(--space-2); align-items: center; }
.col { display: flex; flex-direction: column; gap: 10px; }
.wrap { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.small { margin: 0; font-size: 13px; }
.meta { font-size: 12px; color: var(--muted); }
.list { list-style: none; margin: 0; padding: 0; }
.tight { gap: 6px; }
.panel { max-width: 380px; }
.divider { border-top: 1px solid var(--line); padding-top: var(--space-4); }
.tab { padding: 4px 12px; font-size: 12px; }
.tab[aria-pressed="true"] { border-color: var(--lagoon); }
.body { font-weight: 500; }
h2 { margin: 0; font-size: 18px; font-weight: 600; }
p { margin: 0; }
a { color: var(--accent); }
.gh-arrive { animation: gh-arrive 180ms cubic-bezier(0.23, 1, 0.32, 1); }
@keyframes gh-arrive { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.gh-working::after { content: "…"; display: inline-block; width: 1ch; overflow: hidden; vertical-align: bottom; animation: gh-blink 1.2s steps(4, end) infinite; }
@keyframes gh-blink { from { width: 0; } to { width: 1.1ch; } }
@media (prefers-reduced-motion: reduce) { .gh-arrive { animation: none; } .gh-working::after { animation: none; width: auto; } }

contract.code:
@layer components {
  .gh-card, .gh-muted, .gh-kicker {}            /* var(--line), var(--surface), var(--sea-ink-soft) */
  .gh-input {}                                 /* :focus-visible → 2px var(--lagoon) */
  .gh-btn {} .gh-btn-primary {}                /* the one accent: var(--lagoon-deep) */
  .gh-pill {} .gh-pill[data-tone="live" | "warn"] {}
  .gh-bubble-asked {} .gh-bubble-answer {} .gh-bubble-failed {}
  .gh-arrive { animation: gh-arrive 180ms cubic-bezier(0.23, 1, 0.32, 1); }
  @keyframes gh-arrive { from { opacity: 0; transform: translateY(4px); } }
  @media (prefers-reduced-motion: reduce) { .gh-arrive { animation: none; } }
}

